function clearDownload(){if(lastDownloadUrl)URL.revokeObjectURL(lastDownloadUrl);lastDownloadUrl=null;$('lastDownload').removeAttribute('href');$('downloadNotice').hidden=true}

function dataBytes(data){const comma=data.indexOf(',');if(comma<0||!data.slice(0,comma).startsWith('data:')||!data.slice(0,comma).endsWith(';base64'))throw Error('Formato de archivo local no válido.');return Uint8Array.from(atob(data.slice(comma+1)),c=>c.charCodeAt(0))}
