for(const id of ['camera','gallery'])$(id).onchange=run(async e=>{try{if(batch)throw Error('Cierra el PDF antes de añadir fotografías independientes.');await addPhotos([...e.target.files]);$('checkCode').checked=false}finally{e.target.value=''}});$('clearPhotos').onclick=run(()=>{if(!photos.length||confirm('¿Descartar las fotos actuales?'))clearPhotos()});$('enqueue').onclick=run(async()=>{if(!scanExam||scanExam!==$('active').value||!state.exams.some(e=>e.id===scanExam&&e.plan)||!photos.length||photos.some(p=>!p.check.checked))throw Error('Selecciona prueba y confirma todas las páginas.');const next=structuredClone(state),exam=state.exams.find(e=>e.id===scanExam);let code;const ordered=noCodeBatch(),group=loadedGroup;let batchSource;if(ordered){nextAnonymousGroup(batchRanges,group);batchSource={hash:batch.hash,ordinal:group.student,start:group.start,end:group.end};validateBatchSource(batchSource);code=makeCode(next);}else if(exam.numbering){code=$('assignedCode').value;if(!codes(exam.numbering).includes(code)||!$('checkCode').checked||photos.some(p=>!p.codeCheck.checked))throw Error('Confirma el código impreso de todas las páginas.');if([...next.pending,...next.records].some(x=>x.code===code))throw Error('Este código ya está registrado.')}else code=makeCode(next);if(batch&&!group)throw Error('Abre primero un grupo del PDF.');if(group&&(photos.length!==group.end-group.start+1||(!ordered&&exam.numbering&&code!==studentCode(exam.numbering,group.student))))throw Error('Las páginas o el código no coinciden con el grupo del PDF. Reabre el grupo correcto.');next.pending.push({code,examId:scanExam,requestId:crypto.randomUUID(),...(batchSource?{batchSource}:{}),photos:photos.map(p=>p.c.toDataURL('image/jpeg',.96))});await commit(next);clearPhotos();renderAssignedCode();if(batch&&group){group.saved=true;group.code=code;renderBatchGroups();status(code+' guardado. Selecciona el siguiente alumno del PDF.');}else{status(code+' guardado. Ya puedes fotografiar otro examen o enviarlo a ChatGPT.');go('queue');openPending(code)}});
function openPending(code){selected=code;result=null;const p=state.pending.find(x=>x.code===code),e=state.exams.find(x=>x.id===p.examId);$('exchange').innerHTML=`<div class="item"><h2>${esc(code)} · ${esc(e.title)}</h2><p class="note">${materialManifest(e).length} materiales vinculados y guía validada. No vuelvas a cargar documentos en Auto - GER.</p><details class="item"><summary>Material de referencia vinculado</summary>${materialManifest(e).map(f=>`<p>${esc(materialLabels[f.kind]||f.kind)} · ${esc(f.name)}</p>`).join('')}</details><p>1. Copia las instrucciones.<br>2. Descarga o comparte las páginas JPG. Adjunta todas en el mismo chat de la prueba, donde ya están sus materiales. Si abres otro chat, usa el paquete completo.<br>3. Pega aquí el resultado JSON.</p><div class="actions"><button id="copyCorrection">Copiar instrucciones</button><button id="correctionPack" class="secondary">Descargar páginas e instrucciones (ZIP)</button><button id="correctionFullPack" class="secondary">Descargar paquete completo con referencias (ZIP)</button><button id="sharePhotos" class="secondary">Compartir páginas</button><a class="button secondary" href="https://chatgpt.com/" target="_blank" rel="noopener noreferrer">Abrir ChatGPT ↗</a></div>${p.photos.map((_,i)=>`<details class="item"><summary>Página ${i+1}</summary><img class="page" src="${p.photos[i]}" alt="Página ${i+1}"><button class="secondary" data-photo="${i}">Descargar JPG ${i+1}</button></details>`).join('')}<p class="note">En Plus, adjunta las imágenes directamente, no como PDF escaneado. La app no puede enviar automáticamente archivos a ChatGPT.</p><label for="response">Resultado JSON</label><textarea id="response" rows="4" placeholder="Pega la respuesta"></textarea><label for="responseFile">O importa JSON</label><input type="file" id="responseFile" accept=".json,.txt"><button id="importResult">Importar y revisar</button><div id="review"></div></div>`;$('copyCorrection').onclick=run(()=>copy(correctionPrompt(e,p),code+'-instrucciones.txt'));$('correctionPack').onclick=run(()=>downloadPack(e,correctionPrompt(e,p),code,p,false));$('correctionFullPack').onclick=run(()=>downloadPack(e,correctionPrompt(e,p),code,p,true));$('sharePhotos').onclick=run(async()=>{const files=await Promise.all(p.photos.map(async(s,i)=>new File([dataBytes(s)],`${code}-P${String(i+1).padStart(2,'0')}.jpg`,{type:'image/jpeg'})));if(!navigator.canShare?.({files}))throw Error('No se pueden compartir archivos aquí. Descarga las páginas individualmente.');await navigator.share({files,title:code})});$('exchange').onclick=ev=>{const b=ev.target.closest('[data-photo]');if(b&&!busy){const i=+b.dataset.photo;fileDownload(`${code}-P${String(i+1).padStart(2,'0')}.jpg`,p.photos[i])}};$('responseFile').onchange=run(async ev=>{if(ev.target.files[0]){$('response').value=await ev.target.files[0].text();ev.target.value='';$('response').dispatchEvent(new Event('input'))}});$('response').oninput=()=>{result=null;$('review').replaceChildren()};$('importResult').onclick=run(()=>{result=importResult(e,p,parseJSON($('response').value));showReview(p);status('Resultado asociado correctamente. Revisa los apartados y faltas.')})}
$('pendingList').onclick=run(async ev=>{const b=ev.target.closest('button');if(!b)return;if(b.dataset.open)openPending(b.dataset.open);if(b.dataset.delete&&confirm('¿Eliminar definitivamente este examen pendiente?')){const next=structuredClone(state);next.pending=next.pending.filter(p=>p.code!==b.dataset.delete);await commit(next);if(selected===b.dataset.delete){selected=null;result=null;$('exchange').replaceChildren()}}});
function showReview(p){$('review').innerHTML=`<h2>Revisión docente</h2><div id="gradeLive" class="note"></div><label for="officialInput">Calificación docente (0–10, sin redondeo automático)</label><select id="officialInput"><option value="">Selecciona la calificación</option>${Array.from({length:11},(_,n)=>`<option value="${n}">${n}</option>`).join('')}</select>${result.items.map((i,n)=>`<div class="item"><label>${esc(i.name)} / ${i.max}</label>${i.kind==='map'||i.questionNumber===4?`<select data-points="${n}"><option value="0" ${i.points===0?'selected':''}>0 · Incorrecta</option><option value="${i.max}" ${i.points===i.max?'selected':''}>${i.max} · Correcta (tras verificar)</option></select>`:`<input type="number" min="0" max="${i.max}" step=".01" data-points="${n}" value="${i.points}">`}<p>${esc(i.reason)}</p><label>Punto de mejora (editable)<textarea data-improvement="${n}" rows="2" maxlength="2000">${esc(i.improvement||'')}</textarea></label>${i.kind==='map'?`<p>Topónimo leído: ${esc(i.written)||'—'} · Ubicación: ${esc(i.location)}</p>`:''}${i.review?`<p class="danger">* Lectura o respuesta pendiente de comprobar. La nota es provisional.</p><label class="check"><input type="checkbox" data-resolved="${n}"> He comprobado este apartado en el manuscrito y ajustado su puntuación.</label>`:''}</div>`).join('')}${result.choices?`<h3>Opciones PAU</h3>${[3,4].map(n=>`<label>Cuestión ${n}<select data-choice="${n}">${[['A','Opción A'],['B','Opción B'],['none','Sin respuesta'],['uncertain','Revisar elección']].map(([v,t])=>`<option value="${v}" ${result.choices[n]===v?'selected':''}>${t}</option>`).join('')}</select></label>`).join('')}`:''}<h3>Ortografía</h3>${result.errors.map((e,n)=>`<label class="check"><input type="checkbox" data-error="${n}" ${e.confirmed?'checked':''} ${e.map?'disabled':''}>${esc(e.wrong)} → ${esc(e.right)} ${e.map?'(mapa: no descuenta)':''}</label>`).join('')||'<p>No se han indicado faltas.</p>'}${result.flags.map(f=>`<p class="danger">* ${esc(f)}</p>`).join('')}<label class="check"><input type="checkbox" id="reviewed"> He revisado las respuestas, las dudas, las faltas y la posición de las anotaciones.</label><button id="saveGrade" disabled>Validar nota y conservar examen anotado cifrado</button>`;
 function update(){const copy=structuredClone(result);copy.notes=validateNotes(result.notes,p.photos.length,result.items);for(const el of $('review').querySelectorAll('[data-points]')){if(el.value==='')throw Error('Completa todas las puntuaciones.');const item=copy.items[+el.dataset.points];const points=Number(el.value);if((item.kind==='map'||item.questionNumber===4)&&points!==0&&points!==item.max)throw Error('Cada localización o concepto tipo test PAU vale cero o su puntuación completa.');if(points!==item.points)item.reason+=' [Puntuación ajustada por el docente durante la revisión.]';item.points=points}for(const el of $('review').querySelectorAll('[data-improvement]'))copy.items[+el.dataset.improvement].improvement=el.value.trim();for(const el of $('review').querySelectorAll('[data-error]'))if(!el.disabled)copy.errors[+el.dataset.error].confirmed=el.checked;if(copy.choices){for(const el of $('review').querySelectorAll('[data-choice]'))copy.choices[el.dataset.choice]=el.value;for(const n of [3,4])if(copy.choices[n]==='none'&&copy.items.some(i=>i.questionNumber===n&&i.points!==0))throw Error('Cuestión '+n+' sin respuesta: todos sus apartados deben valer cero.')}let g=grade(copy);if($('officialInput').value!=='')g=assignOfficial(g,$('officialInput').value);$('gradeLive').textContent=`Calificación docente: ${officialLabel(g)} · Cálculo técnico exacto: ${exactLabel(g)} · Inicial: ${g.total.toFixed(2)} · Ortografía: −${g.penalty.toFixed(2)}`;return {copy,g}}
 $('review').insertAdjacentHTML('beforeend','<div id="annotationEditor"></div><button id="downloadCorrected" class="secondary">Descargar borrador anotado (PDF)</button>');renderAnnotationEditor(p);$('downloadCorrected').onclick=run(async()=>{const {copy,g}=update();await exportCorrection({...p,result:copy,grade:g,provisional:true})});update();$('review').oninput=ev=>{if(ev.target.id!=='reviewed')$('reviewed').checked=false;try{update();$('saveGrade').disabled=!$('reviewed').checked||$('officialInput').value===''}catch(err){$('saveGrade').disabled=true;$('gradeLive').textContent=err.message}};$('saveGrade').onclick=run(async()=>{if(!result||selected!==p.code||!$('reviewed').checked)throw Error('Revisa primero la corrección.');const {copy,g}=update();if(officialGrade(g)===null)throw Error('Selecciona la calificación docente antes de validar.');if([...$('review').querySelectorAll('[data-resolved]')].some(el=>!el.checked))throw Error('Confirma cada apartado de lectura dudosa antes de validar.');if(copy.choices&&Object.values(copy.choices).includes('uncertain'))throw Error('Confirma primero la opción PAU dudosa.');copy.reviewCompleted=true;const next=structuredClone(state);if(!next.pending.some(x=>x.code===p.code)||next.records.some(x=>x.code===p.code))throw Error('Examen ya validado o eliminado.');next.records.push({code:p.code,examId:p.examId,result:copy,grade:g,photos:[...p.photos],...(p.batchSource?{batchSource:p.batchSource}:{})});next.pending=next.pending.filter(x=>x.code!==p.code);await commit(next);selected=result=null;$('exchange').replaceChildren();go('grades');status(p.code+' validado: '+officialLabel(g)+'/10 · Técnica: '+exactLabel(g)+'. El examen anotado queda guardado en Calificaciones hasta que lo elimines.')})}
async function correctionRecord(record){const images=[];for(const data of record.photos){const img=new Image();img.src=data;await img.decode();images.push({bytes:dataBytes(data),width:img.naturalWidth,height:img.naturalHeight})}const title=state.exams.find(e=>e.id===record.examId)?.title||'Prueba escrita';return {...record,title:record.batchSource?title+' · Examen nº '+record.batchSource.ordinal+' del PDF':title,images}}
async function exportCorrection(record){download(record.code+(record.provisional?'-borrador-anotado.pdf':'-corregido.pdf'),correctedPDF(await correctionRecord(record)),'application/pdf');status('PDF anotado preparado. Comprueba la descarga.')}
function feedbackRecord(r){const title=state.exams.find(e=>e.id===r.examId)?.title||'Prueba escrita';return {...r,title};}
function scopedRecords(){const scope=$('gradeScope').value;return state.records.filter(r=>scope===ALL||r.examId===scope).sort((a,b)=>a.code.localeCompare(b.code,'es',{numeric:true}));}
async function exportPair(records,base,format){if(!records.length)throw Error('No hay correcciones validadas en esta selección.');if(format==='feedback'){download(base+'-informe.pdf',feedbackPDF(records.map(feedbackRecord)),'application/pdf');return;}const available=records.filter(r=>r.photos?.length);if(available.length!==records.length)throw Error('Hay correcciones sin imágenes conservadas. Descarga sus informes por separado.');if(available.reduce((n,r)=>n+r.photos.length,0)>150)throw Error('Máximo 150 hojas por exportación conjunta. Selecciona una prueba más pequeña.');const ready=[];for(const r of available)ready.push(await correctionRecord(r));const pdf=overlaidPDF(ready);if(format==='overlaid')download(base+'-examen-anotado.pdf',pdf,'application/pdf');else download(base+'-correccion.zip',zipStore([[base+'-examen-anotado.pdf',pdf],[base+'-informe.pdf',feedbackPDF(records.map(feedbackRecord))]]),'application/zip');status('Descarga preparada. El original permanece intacto.');}
$('records').onclick=run(async ev=>{const b=ev.target.closest('button');if(!b)return;const d=b.dataset;if(d.assignOfficial){const next=structuredClone(state),r=next.records.find(r=>r.code===d.assignOfficial);const el=[...$('records').querySelectorAll('[data-official-edit]')].find(x=>x.dataset.officialEdit===d.assignOfficial);if(!r||!el)throw Error('Corrección no encontrada.');r.grade=assignOfficial(r.grade,el.value);await commit(next);status('Calificación docente guardada: '+officialLabel(r.grade)+' · Técnica: '+exactLabel(r.grade));return;}const code=d.corrected||d.overlaid||d.feedback||d.both;if(!code)return;const r=state.records.find(r=>r.code===code);if(!r)throw Error('Corrección no encontrada.');if(d.corrected)await exportCorrection(r);else await exportPair([r],code,d.overlaid?'overlaid':d.feedback?'feedback':'both');});
for(const [id,format] of [['allOverlaid','overlaid'],['allFeedback','feedback'],['allPair','both']])$(id).onclick=run(()=>exportPair(scopedRecords(),'auto-ger-clase',format));
function renderAnnotationEditor(p){const box=$('annotationEditor');result.notes??=[];box.innerHTML=`<h3>Anotaciones sobre manuscritos</h3><p class="note">Verde: acierto · Rojo: error propuesto, sujeto a revisión · Ocre: omisión o duda · Azul: observación. Las regiones propuestas son aproximadas. Los números están fuera de la escritura. Revisa cada marca; si no es segura, déjala al margen.</p><label for="notePage">Hoja</label><select id="notePage">${p.photos.map((_,i)=>`<option value="${i+1}">Página ${i+1}</option>`).join('')}</select><label for="annotationZoom">Ampliación del manuscrito</label><select id="annotationZoom"><option value="1">Ajustar a pantalla</option><option value="1.5">150 %</option><option value="2">200 %</option><option value="3">300 %</option></select><p id="annotationMode" role="status" aria-live="polite"></p><div id="annotatedView"></div><button class="secondary" id="downloadReviewPage">Descargar hoja sin anotaciones (JPG)</button><label for="noteKind">Tipo</label><select id="noteKind">${Object.entries(noteKinds).map(([k,v])=>`<option value="${k}">${esc(v)}</option>`).join('')}</select><label for="noteQuote">Fragmento leído (opcional)</label><input id="noteQuote" maxlength="500"><label for="noteComment">Corrección / explicación</label><textarea id="noteComment" maxlength="2000" rows="3"></textarea><button class="secondary" id="addNote">Añadir anotación al margen</button><div id="noteList"></div>`;
 let marking=-1,first=null;const changed=()=>{$('reviewed').checked=false;$('saveGrade').disabled=true};const colors={red:'#ab2121',green:'#196b40',ochre:'#80500a',amber:'#80500a',blue:'#28578a'};
 function mode(s=''){ $('annotationMode').textContent=s; }
 function paint(){const page=+$('notePage').value,view=$('annotatedView');view.replaceChildren();const c=document.createElement('canvas'),im=new Image();c.setAttribute('aria-label','Página manuscrita '+page+' con anotaciones numeradas');view.append(c);im.onload=()=>{if(!c.isConnected)return;const scale=Math.min(1,3000/Math.max(im.naturalWidth,im.naturalHeight)),w=Math.round(im.naturalWidth*scale),h=Math.round(im.naturalHeight*scale),rail=Math.max(48,w*.08);c.width=w+rail;c.height=h;const zoom=+$('annotationZoom').value;c.dataset.zoom=String(zoom);const ctx=c.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(im,0,0,w,h);const f=scale/Math.min(540/im.naturalWidth,710/im.naturalHeight);const rows=result.notes.map((n,i)=>({...n,num:i+1})).filter(n=>n.page===page);for(const m of markGeometry(rows,w/f,h/f)){const b=m.region,pt=m.point;ctx.strokeStyle=ctx.fillStyle=colors[m.color];ctx.lineWidth=Math.max(2,f*1.15);ctx.beginPath();if(b){if(m.kind==='map')ctx.rect(b.x*f,b.y*f,b.w*f,b.h*f);else{const y=(b.y+b.h+1)*f;if(m.kind==='spelling'){ctx.setLineDash([2*f,2*f]);ctx.moveTo(b.x*f,y);ctx.lineTo((b.x+b.w)*f,y)}else{ctx.moveTo(b.x*f,y-3*f);ctx.lineTo(b.x*f,y);ctx.lineTo((b.x+b.w)*f,y);ctx.lineTo((b.x+b.w)*f,y-3*f)}}}else if(pt){ctx.moveTo((pt.x-4)*f,pt.y*f);ctx.lineTo((pt.x+4)*f,pt.y*f);ctx.moveTo(pt.x*f,(pt.y-4)*f);ctx.lineTo(pt.x*f,(pt.y+4)*f)}ctx.stroke();ctx.setLineDash([]);const mx=w+rail/2,my=m.railY*f;ctx.strokeRect(mx-9*f,my-7*f,18*f,14*f);ctx.font='bold '+Math.max(12,8*f)+'px Arial';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(String(m.num),mx,my)}if(first){ctx.fillStyle='#28578a';ctx.beginPath();ctx.arc(first.x*w,first.y*h,5*f,0,Math.PI*2);ctx.fill()}
 c.onclick=ev=>{if(marking<0||busy)return;const n=result.notes[marking];if(!n||n.page!==page)return;const r=c.getBoundingClientRect(),px=(ev.clientX-r.left)/r.width*c.width/w,py=(ev.clientY-r.top)/r.height;if(px<0||px>1||py<0||py>1)return;if(!first){first={x:px,y:py};mode('Pulsa ahora la esquina opuesta del fragmento.');paint();return}const region={x:Math.min(first.x,px),y:Math.min(first.y,py),w:Math.abs(first.x-px),h:Math.abs(first.y-py)};if(region.w<.003||region.h<.003){first=null;mode('Región demasiado pequeña. Selecciona las dos esquinas de nuevo.');paint();return}n.region=region;n.source='teacher';delete n.anchor;marking=-1;first=null;mode('Región actualizada.');changed();paint();list()};};im.src=p.photos[page-1]}
 function list(){$('noteList').innerHTML=result.notes.map((n,i)=>`<div class="item"><b>${i+1}. Hoja ${n.page} · ${esc(noteKinds[n.kind])}</b><p>${n.region||n.anchor?'Marca en hoja · '+(n.source==='teacher'?'ajustada por docente':'propuesta, comprobar'):'Solo margen'}${n.reading==='uncertain'||n.reading==='partial'?' · Lectura pendiente':''}</p><label>Fragmento (literal si se lee)<input data-note-quote="${i}" maxlength="500" value="${esc(n.quote)}"></label><label>Tipo<select data-note-kind="${i}">${Object.entries(noteKinds).map(([k,v])=>`<option value="${k}" ${k===n.kind?'selected':''}>${esc(v)}</option>`).join('')}</select></label><label>Lectura<select data-note-reading="${i}">${[['clear','Legible'],['partial','Parcial'],['uncertain','Dudosa'],['not_applicable','No procede']].map(([k,v])=>`<option value="${k}" ${k===(n.reading||'not_applicable')?'selected':''}>${v}</option>`).join('')}</select></label><label>Explicación<textarea data-note-edit="${i}" rows="2" maxlength="2000">${esc(n.comment)}</textarea></label><div class="actions"><button class="secondary" data-note-mark="${i}">${n.region||n.anchor?'Ajustar región':'Marcar región'}</button><button class="secondary" data-note-unmark="${i}">Dejar al margen</button><button class="secondary danger" data-note-remove="${i}">Eliminar</button></div></div>`).join('')||'<p>No hay anotaciones. Añade las que correspondan antes de validar.</p>'}
 $('notePage').onchange=()=>{marking=-1;first=null;mode();paint()};$('annotationZoom').onchange=paint;$('downloadReviewPage').onclick=run(()=>fileDownload(`${p.code}-P${String($('notePage').value).padStart(2,'0')}.jpg`,p.photos[+$('notePage').value-1]));$('addNote').onclick=run(()=>{const n={page:+$('notePage').value,itemId:'',kind:$('noteKind').value,quote:$('noteQuote').value,comment:$('noteComment').value,source:'teacher'};result.notes=validateNotes([...result.notes,n],p.photos.length,result.items);$('noteQuote').value='';$('noteComment').value='';changed();list();paint()});$('noteList').oninput=ev=>{const d=ev.target.dataset;if(d.noteEdit!==undefined){result.notes[+d.noteEdit].comment=ev.target.value;changed()}else if(d.noteQuote!==undefined){result.notes[+d.noteQuote].quote=ev.target.value;result.notes[+d.noteQuote].source='teacher';changed()}else if(d.noteReading!==undefined){const n=result.notes[+d.noteReading];n.reading=ev.target.value;n.source='teacher';if(n.reading!=='clear'){delete n.region;delete n.anchor}changed();paint()}else if(d.noteKind!==undefined){const n=result.notes[+d.noteKind];n.kind=ev.target.value;n.source='teacher';if(['review','omission','general'].includes(n.kind)){delete n.region;delete n.anchor}changed();paint()}};$('noteList').onclick=ev=>{const b=ev.target.closest('button');if(!b||busy)return;if(b.dataset.noteRemove!==undefined){result.notes.splice(+b.dataset.noteRemove,1);marking=-1;first=null;changed();list();paint()}else if(b.dataset.noteUnmark!==undefined){const n=result.notes[+b.dataset.noteUnmark];delete n.anchor;delete n.region;marking=-1;first=null;changed();list();paint()}else if(b.dataset.noteMark!==undefined){marking=+b.dataset.noteMark;first=null;$('notePage').value=result.notes[marking].page;mode('Marca la esquina superior izquierda y luego la inferior derecha del fragmento.');paint();$('annotatedView').scrollIntoView({block:'center'})}};list();paint()}
function downloadGrades(id,format){const f=gradeFile(state,id,format);download(f.name,f.bytes,f.mime);status(format.toUpperCase()+' preparado. Comprueba el archivo descargado; contiene únicamente las notas validadas.')}
for(const [button,format] of [['csv','csv'],['gradePdf','pdf'],['gradeOdt','odt']])$(button).onclick=run(()=>downloadGrades($('gradeScope').value,format));
