function validateState(s){if(!s||!Array.isArray(s.exams)||!Array.isArray(s.pending)||!Array.isArray(s.records)||!Number.isSafeInteger(s.next)||s.next<1)throw Error('Copia incompatible.');const ids=new Set(),codes=new Set();for(const e of s.exams){if(typeof e.id!=='string'||ids.has(e.id)||typeof e.title!=='string'||!Object.keys(kinds).every(k=>Array.isArray(e.materials?.[k])&&(!e.plan||e.materials[k].length)&&e.materials[k].every(f=>typeof f.name==='string'&&typeof f.data==='string'&&/^data:[^,]*;base64,/.test(f.data))))throw Error('Materiales inválidos en copia.');if(e.plan)validatePlan(e.plan);if(e.numbering){numbering(e.numbering);if(e.createdExam)validateExam(e.createdExam)}ids.add(e.id)}for(const p of [...s.pending,...s.records]){if(!belongs(s.exams.find(e=>e.id===p.examId),p.code)||codes.has(p.code)||!s.exams.find(e=>e.id===p.examId)?.plan||(p.code.startsWith('EX-')&&Number(p.code.slice(3))>=s.next))throw Error('Código inválido en copia.');codes.add(p.code);if(p.batchSource){validateBatchSource(p.batchSource);if(!p.code.startsWith('EX-')||p.photos?.length!==p.batchSource.end-p.batchSource.start+1)throw Error('Referencia de PDF sin código incoherente.')}}for(const p of s.pending){if(typeof p.requestId!=='string'||!Array.isArray(p.photos)||!p.photos.length||p.photos.length>20||p.photos.some(x=>typeof x!=='string'||!/^data:image\/jpeg;base64,[A-Za-z0-9+/=]+$/.test(x)))throw Error('Fotos inválidas en copia.')}for(const r of s.records){if(r.photos!==undefined){if(!Array.isArray(r.photos)||!r.photos.length||r.photos.length>20||r.photos.some(x=>typeof x!=='string'||!/^data:image\/jpeg;base64,[A-Za-z0-9+/=]+$/.test(x)))throw Error('Imágenes de corrección inválidas');validateNotes(r.result.notes,r.photos.length,r.result.items)}const g=calculate(r.result.items,r.result.errors);if(['final','total','penalty'].some(k=>g[k]!==r.grade[k]))throw Error('Nota incoherente en copia.');officialGrade(r.grade)}validateClasses(s.classes||[]);return migrateLibrary(s)}
$('restore').onchange=run(async e=>{try{if(!e.target.files[0])return;const restored=validateState(await decryptBackup(JSON.parse(await e.target.files[0].text()),$('password').value));if(!confirm('¿Reemplazar todos los datos locales y descartar fotos actuales?'))return;await commit(restored);resetUI();status('Copia restaurada.')}finally{e.target.value='';$('password').value=''}});function renderCleanup(){const prev=$('cleanupScope').value;$('cleanupScope').innerHTML='<option value="">Selecciona una opción</option>'+state.exams.map(e=>`<option value="${esc(e.id)}">${esc(e.title)}</option>`).join('')+`<option value="${ALL}">Toda la aplicación (este dispositivo)</option>`;$('cleanupScope').value=prev===ALL||state.exams.some(e=>e.id===prev)?prev:'';resetCleanupConfirm()}
