$('reuseFiles').onclick=run(async()=>{if(draft.plan)throw Error('Prueba bloqueada.');const chosen=[...$('reuseList').querySelectorAll('input:checked')];if(!chosen.length)throw Error('Selecciona al menos un archivo.');const entries=chosen.map(c=>c._material);const replace=$('replaceLinked').checked;if(replace&&!confirm('¿Sustituir los materiales vinculados a este borrador? Se reinicia la selección de imágenes del generador si aún no has generado el examen. La biblioteca no se modifica.'))return;const base=replace?{model:draft.createdPages?draft.materials.model:[],content:[],rubric:[]}:draft.materials;const nextMaterials=attachMaterials(base,entries,{skipModel:!!draft.createdPages});if(!draft.createdPages&&workflowMode==='create'){const images=new Map();for(const f of materialManifest({materials:nextMaterials})){if(!/^data:image\/(?:png|jpeg|webp);base64,/.test(f.data))continue;if(images.has(f.name)&&images.get(f.name)!==f.data)throw Error('Dos imágenes distintas se llaman '+f.name+'. Selecciona solo una o renombra el archivo en tu dispositivo.');images.set(f.name,f.data)}const previousFigures=structuredClone(figures);try{if(replace)figures=Object.create(null);for(const f of entries){const mime=/^data:(image\/(?:png|jpeg|webp));base64,/.exec(f.data)?.[1];if(mime)await addFigure(new File([dataBytes(f.data)],f.name,{type:mime}));}}catch(err){figures=previousFigures;throw err}}draft.materials=nextMaterials;draft.workflowMode=workflowMode;$('replaceLinked').checked=false;draft.title=$('title').value.trim()||state.library.find(f=>f.id===$('reuseFolder').value)?.title||'Nueva prueba';renderDraft();await saveDraft(false);$('reusePanel').open=false;if(workflowMode==='correct'){$('creatorPanel').open=false;$('guidePanel').scrollIntoView({block:'start'});}else $('creatorPanel').open=true;status('Material vinculado y guardado. No es necesario volver a subirlo.');});
