async function addFigure(file){if(!file.size||file.size>20*1024*1024)throw Error('Imagen vacía o de más de 20 MB.');const url=URL.createObjectURL(file),img=new Image();try{img.src=url;await img.decode();const c=document.createElement('canvas'),factor=Math.min(1,2400/Math.max(img.naturalWidth,img.naturalHeight));c.width=Math.max(1,Math.round(img.naturalWidth*factor));c.height=Math.max(1,Math.round(img.naturalHeight*factor));const ctx=c.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(img,0,0,c.width,c.height);figures[file.name]={data:c.toDataURL('image/jpeg',.94),width:c.width,height:c.height};c.width=c.height=0}finally{URL.revokeObjectURL(url)}}
