function decodeFigures(f){return Object.fromEntries(Object.entries(f||{}).map(([k,v])=>[k,{width:v.width,height:v.height,bytes:dataBytes(v.data)}]))}
function layoutFor(model,fig){const canvas=document.createElement('canvas'),ctx=canvas.getContext('2d');return layoutExam(model,fig,(text,size,bold)=>{ctx.font=`${bold?'bold ':''}${size}px Arial`;return ctx.measureText(text).width*1.04})}
async function checkCreator(){creatorReady();const n=readNumbering();if(state.exams.some(e=>e.id!==draft.id&&e.numbering&&prefix(e.numbering)===prefix(n)))throw Error('Ya existe una prueba con este tema, materia, grupo y número de prueba escrita. Elige otro número.');if($('creatorMode').value==='existing'){if($('creatorFormat').value==='pau')throw Error('Para validar automáticamente el formato PAU, usa Crear/adaptar con editor. Para reproducir un PDF existente, selecciona PAU adaptable.');if($('existingSource').value==='')throw Error('Selecciona un PDF de examen existente.');if(!confirm('El PDF existente se reproduce como imagen. Comprueba que no contiene avisos de puntuación decimal; si los contiene, adapta el examen en el editor. ¿Continuar?'))throw Error('Reproducción cancelada.');const file=draft.materials.model[+$('existingSource').value];if(!file)throw Error('PDF no seleccionado.');const scan=await openScan(new File([dataBytes(file.data)],file.name,{type:'application/pdf'}));const figData=Object.create(null);try{if(scan.count>20)throw Error('Máximo 20 páginas por examen existente.');for(let i=1;i<=scan.count;i++){const page=await scan.page(i),url=URL.createObjectURL(page),img=new Image();try{img.src=url;await img.decode();figData['original-'+String(i).padStart(2,'0')+'.jpg']={width:img.naturalWidth,height:img.naturalHeight,data:await read(page)}}finally{URL.revokeObjectURL(url)}}}finally{await scan.close()}const fig=decodeFigures(figData),pages=layoutExisting(fig);return {n,model:null,fig,figData,pages,source:file.data,mode:'existing',originalName:file.name}}if(editorDirty)throw Error('Pulsa Aplicar preguntas antes de generar la muestra.');const parsed=parseJSON($('creatorJson').value);const model=$('creatorFormat').value==='pau'?validatePauExam(parsed):validatePauCustomExam(parsed);if(model.questions.some(q=>/\[(?:Pregunta|Cinco conceptos|Localizaciones|Explicación|Noticia)/i.test(q.text)))throw Error('Completa los marcadores de la plantilla.');model.title=draft.title;const fig=decodeFigures(figures),pages=layoutFor(model,fig);return {n,model,fig,figData:structuredClone(figures),pages,source:$('creatorJson').value,mode:'new'}}
$('saveModelToLibrary').onclick=run(async()=>{if(!draft.createdPages||!draft.materials.model.length)throw Error('Genera el modelo primero.');const next=structuredClone(state);next.library=addLibraryFiles(next.library,$('modelFolder').value,[{...draft.materials.model[0],kind:'model'}]);await commit(next);renderReuse();status('Modelo guardado en el repositorio independiente.');});
$('previewExam').onclick=run(async()=>{const c=await checkCreator();await saveDraft(false);c.format=$('creatorFormat').value;checkedCreation=c;$('approveExam').checked=false;$('creatorPreview').textContent=`${c.model?c.model.questions.length+' preguntas · 10 puntos · ': 'PDF existente · '}${c.pages.length} páginas por alumno · ${c.pages.length*c.n.count} páginas en total. Revisa el PDF de muestra antes de confirmar.`;download('muestra-'+studentCode(c.n,1)+'.pdf',makePDF(c.pages,[studentCode(c.n,1)],c.fig,{header:$('printHeader').value.trim()}),'application/pdf')});
$('createClassPdf').onclick=run(async()=>{if(draft.createdPages){const n=numbering(draft.numbering),fig=decodeFigures(draft.createdFigures);download(prefix(n)+'clase.pdf',makePDF(draft.createdPages,codes(n),fig,{legacy:draft.templateVersion!==10,header:draft.printHeader}),'application/pdf');return}if(draft.plan)throw Error('Prueba bloqueada.');const c=checkedCreation;if(!c||!$('approveExam').checked||JSON.stringify(c.n)!==JSON.stringify(readNumbering())||c.mode!==$('creatorMode').value||c.format!==$('creatorFormat').value||c.source!==(c.mode==='existing'?draft.materials.model[+$('existingSource').value]?.data:$('creatorJson').value))throw Error('Comprueba y descarga la muestra; revisa el examen y confirma antes de generar.');if(c.mode==='new'&&draft.materials.model.length&&!confirm('¿Sustituir los modelos del borrador por el PDF generado?'))return;const modelPdf=makePDF(c.pages,['MODELO SIN IDENTIFICACIÓN'],c.fig,{header:$('printHeader').value.trim()}),classPdf=makePDF(c.pages,codes(c.n),c.fig,{header:$('printHeader').value.trim()});const modelData=await read(new File([modelPdf],'modelo-'+prefix(c.n)+'sin-codigo.pdf',{type:'application/pdf'}));const next=structuredClone(state),created=structuredClone(draft);created.numbering=c.n;created.printHeader=$('printHeader').value.trim();created.classId=draft.classId||null;created.createdExam=c.model;created.createdPages=c.pages;created.createdFigures=c.figData;created.templateVersion=10;created.examStyle=c.format;delete created.creator;created.materials.model=[{name:'modelo-'+prefix(c.n)+'sin-codigo.pdf',data:modelData}];if(c.mode==='existing')created.materials.model.push({name:c.originalName,data:c.source});const i=next.exams.findIndex(e=>e.id===draft.id);if(i>=0&&next.exams[i].plan)throw Error('Prueba bloqueada.');if(i<0)next.exams.push(created);else next.exams[i]=created;await commit(next);draft=structuredClone(created);renderDraft();download(prefix(c.n)+'clase.pdf',classPdf,'application/pdf');status('PDF generado y modelo guardado. Prepara ahora la guía de corrección con los mismos materiales.');});
function renderAssignedCode(){const exam=state.exams.find(e=>e.id===$('active').value);$('scanLinked').textContent=exam?`${exam.title} · ${materialManifest(exam).length} documentos vinculados · guía validada`:'Selecciona una prueba ya validada o crea una corrección nueva.';const box=$('assignedCodeBox'),select=$('assignedCode'),old=select.value;box.hidden=noCodeBatch()||!exam?.numbering;select.replaceChildren(new Option('Selecciona código impreso',''));if(noCodeBatch()||!exam?.numbering)return;const used=new Set([...state.pending,...state.records].map(p=>p.code));for(const code of codes(exam.numbering)){if(!used.has(code))select.add(new Option(code,code))}select.value=[...select.options].some(o=>o.value===old)?old:'';if(select.value!==old)$('checkCode').checked=false;}
