function closeBatch(){if(batch)Promise.resolve(batch.close()).catch(()=>{});batch=null;batchMode='printed';batchRanges=[];loadedGroup=null;$('batchControls').hidden=true;$('batchInfo').textContent='Selecciona una prueba validada y un PDF. No se sube a GitHub.';$('ranges').value='';$('batchGroup').replaceChildren();$('batchPdf').value='';renderAssignedCode();}
function renderBatchGroups(){const sel=$('batchGroup');sel.replaceChildren();for(const [i,r] of batchRanges.entries()){const o=new Option(`${noCodeBatch()?'Examen del PDF nº ':'Alumno '}${String(r.student).padStart(2,'0')} · páginas ${r.start}–${r.end}${r.saved?' ✓ '+(r.code||'guardado'):''}`,String(i));o.disabled=!!r.saved||(noCodeBatch()&&i!==batchRanges.findIndex(x=>!x.saved));sel.add(o)}const first=batchRanges.findIndex(r=>!r.saved);sel.value=first<0?'':String(first);$('loadGroup').disabled=first<0;$('batchInfo').textContent=batch?`${batch.count} páginas · ${batchRanges.filter(r=>r.saved).length}/${batchRanges.length} grupos guardados. ${noCodeBatch()?'Comprueba el orden y la separación.':'Comprueba el orden y los códigos impresos.'}`:''}
