async function openBatchFile(file){if(!file||!$('active').value)throw Error('Selecciona una prueba validada.');if((photos.length||batch)&&!confirm('¿Cerrar el PDF anterior y descartar páginas sin guardar?'))return;clearPhotos();closeBatch();$('batchInfo').textContent='Abriendo PDF localmente…';try{batch=await openScan(file)}catch(err){$('batchInfo').textContent=err.message;throw err}$('batchControls').hidden=false;scanExam=$('active').value;const exam=state.exams.find(e=>e.id===scanExam);const previous=[...state.pending,...state.records].some(r=>r.examId===scanExam&&r.batchSource?.hash===batch.hash);batchMode=previous||!exam?.numbering?'ordered':'printed';$('batchMode').options[0].disabled=!exam?.numbering||previous;showBatchMode();renderBatchGroups();status('PDF abierto en el dispositivo. Configura la separación por alumno.');return true}
$('batchPdf').onchange=run(async e=>{const file=e.target.files[0];try{if(!file)return;if(!$('active').value){if(startFromRepository('correct',null,file))status('PDF seleccionado. Vincula los materiales y valida la guía una sola vez.');return}await openBatchFile(file)}finally{e.target.value=''}});
function setBatchRanges(raw){if(!batch)throw Error('Abre un PDF primero.');if(photos.length)throw Error('Guarda o descarta las páginas abiertas antes de cambiar los intervalos.');if(batchRanges.some(r=>r.saved))throw Error('Ya hay grupos guardados. Cierra y vuelve a abrir el PDF para cambiar los intervalos.');const exam=state.exams.find(e=>e.id===scanExam);if(noCodeBatch()){batchRanges=anonymousBatchGroups(batch.count,raw,[...state.pending,...state.records].filter(r=>r.examId===scanExam),batch.hash);$('ranges').value=batchRanges.map(r=>`${r.start}-${r.end}`).join('\n');renderBatchGroups();status(`${batchRanges.length} exámenes · ${batch.count} páginas. Se guardarán por orden del PDF.`);return;}const ranges=splitRanges(batch.count,raw);if(exam?.numbering)for(const r of ranges)studentCode(exam.numbering,r.student);const used=new Set([...state.pending,...state.records].map(p=>p.code));batchRanges=ranges.map(r=>({...r,saved:!!exam?.numbering&&used.has(studentCode(exam.numbering,r.student))}));$('ranges').value=ranges.map(r=>`${String(r.student).padStart(2,'0')}: ${r.start}-${r.end}`).join('\n');renderBatchGroups();const covered=ranges.reduce((n,r)=>n+r.end-r.start+1,0);status(`${ranges.length} alumnos · ${covered}/${batch.count} páginas asignadas.${covered<batch.count?' Atención: hay páginas sin asignar.':''}`)}
