try{const stored=await openDB();const existing=isVault(stored);$('gateTitle').textContent=existing?'Desbloquear Auto - GER':'Crea tu contraseña';$('gateInfo').textContent=existing?'Introduce tu contraseña para descifrar tus datos.':stored?'Se cifrarán los datos de la versión anterior. Conserva una copia de seguridad.':'Elige una contraseña larga (12 caracteres como mínimo). No se guarda la contraseña.';$('confirmBox').hidden=existing;$('vaultConfirm').required=!existing;$('unlock').textContent=existing?'Desbloquear':'Crear y acceder';$('gateForm').hidden=false;$('gateForm').onsubmit=async ev=>{ev.preventDefault();if(busy)return;busy=true;$('unlock').disabled=true;$('gateError').textContent='';try{const password=$('vaultPassword').value;if(!existing&&password!==$('vaultConfirm').value)throw Error('Las contraseñas no coinciden.');const salt=existing?stored.salt:newSalt();const key=await deriveVaultKey(password,salt);let loaded;if(existing){loaded=validateState(await unseal(stored,key))}else{loaded=stored?validateState(stored):empty();loaded.revision=(stored?.revision||0)+1;await writeVault(await seal(loaded,key,salt),{revision:stored?.revision||0,exists:!!stored,encrypted:false})}vaultKey=key;vaultSalt=salt;state=migrateLibrary(loaded);draft=fresh();render();renderLibrary();renderDraft();renderCleanup();ready=true;$('gate').remove();$('workspace').hidden=false;$('workspace').inert=false;$('navigation').hidden=false;$('navigation').inert=false;$('lockNow').hidden=false;go('home');$('storage').textContent='Almacenamiento local cifrado operativo. Realiza copias de seguridad.';armIdle()}catch(err){$('gateError').textContent=err.message; $('vaultPassword').value='';$('vaultConfirm').value=''}finally{busy=false;if($('unlock'))$('unlock').disabled=false}}}catch(err){$('gateError').textContent='No se pudo abrir la base de datos: '+err.message}
