function renderClassMembers(){const c=(state.classes||[]).find(x=>x.id===$('classSelect').value);$('classMembers').innerHTML=c?`<h3>${esc(c.title)} · ${c.students.length} alumnos</h3>`+c.students.map(s=>`<p><b>${String(s.number).padStart(2,'0')}</b> · ${esc(s.name)}</p>`).join(''):'Selecciona o crea una clase.'}
$('classSelect').onchange=renderClassMembers;
$('createRoster').onclick=run(async()=>{const title=$('classTitle').value.trim();if(!title||title.length>100)throw Error('Escribe el nombre de la clase.');if(state.classes.some(c=>c.title===title))throw Error('Ya existe esta clase.');const next=structuredClone(state),id=crypto.randomUUID();next.classes.push({id,title,students:[]});await commit(next);$('classSelect').value=id;$('classTitle').value='';renderClassMembers();status('Clase creada.')});
let rosterRows=[];
$('rosterFile').onchange=run(async ev=>{try{if(!ev.target.files[0])return;const text=await ev.target.files[0].text();if(!text||text.length>1000000)throw Error('CSV vacío o demasiado grande.');const variants=[';','\t',','].flatMap(sep=>{try{return [parseTable(text,sep)]}catch{return []}});if(!variants.length)throw Error('No se pudo leer el CSV.');rosterRows=variants.sort((a,b)=>(b[0]?.length||0)-(a[0]?.length||0))[0];if(rosterRows.length<2)throw Error('El CSV debe incluir encabezado y alumnos.');$('rosterColumn').replaceChildren(...rosterRows[0].map((x,i)=>new Option(x||'Columna '+(i+1),i)));$('rosterPreview').textContent=rosterRows.slice(0,4).map(r=>r.join(' | ')).join('\n');status('Selecciona la columna de nombres completos y verifica la muestra.')}finally{ev.target.value=''}});
$('addRoster').onclick=run(async()=>{const id=$('classSelect').value;const next=structuredClone(state),i=next.classes.findIndex(c=>c.id===id);if(i<0)throw Error('Crea o selecciona la clase.');const names=$('rosterNames').value.trim()?$('rosterNames').value.split(/\r?\n/):rosterRows.slice(1).map(r=>r[+$('rosterColumn').value]||'');if(!names.some(n=>n.trim()))throw Error('No hay nombres para añadir.');next.classes[i]=addStudents(next.classes[i],names);await commit(next);$('classSelect').value=id;renderClassMembers();$('rosterNames').value='';rosterRows=[];$('rosterPreview').textContent='';$('rosterColumn').replaceChildren();status('Alumnos guardados. Los números existentes no cambian.')});
function renderClassPicker(){const sel=$('creatorClass');sel.replaceChildren(new Option('Sin clase vinculada',''),...(state.classes||[]).map(c=>new Option(c.title,c.id)));sel.value=draft.classId||'';sel.disabled=!!draft.plan||!!draft.createdPages;}
$('creatorClass').onchange=()=>{draft.classId=$('creatorClass').value||null;const c=state.classes.find(c=>c.id===draft.classId);if(c?.students.length)$('studentCount').value=Math.max(...c.students.map(s=>s.number));invalidateCreator();updateCodePreview()};
$('linkClass').onclick=run(async()=>{const e=state.exams.find(x=>x.id===$('idoExam').value),c=state.classes.find(x=>x.id===$('idoClass').value);if(!e?.numbering||!c?.students.length)throw Error('Selecciona prueba y clase con alumnado.');if(e.classId&&e.classId!==c.id)throw Error('La prueba ya está vinculada a otra clase.');if(!confirm('Confirma que los números de alumno impresos coinciden EXACTAMENTE con los de esta clase. No se pueden deducir automáticamente.'))return;const next=structuredClone(state);next.exams.find(x=>x.id===e.id).classId=c.id;await commit(next);if(draft?.id===e.id)draft.classId=c.id;status('Clase vinculada a la prueba.')});
function exportIdo(format){const rows=rowsForClass(state,$('idoExam').value,$('idoClass').value,$('idoBoth').checked);if(!rows.slice(1).some(r=>r.slice(1).some(n=>typeof n==='number')))throw Error('No hay notas validadas para esta clase.');if(!confirm('El archivo incluirá nombres reales. Guárdalo de forma privada. ¿Continuar?'))return;download('auto-ger-idoceo.'+format,format==='xlsx'?classXLSX(rows):classCSV(rows),format==='xlsx'?'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet':'text/csv;charset=utf-8');status('Archivo preparado. Importa en la clase existente de iDoceo y comprueba las coincidencias.')}
$('idoCSV').onclick=run(()=>exportIdo('csv'));$('idoXLSX').onclick=run(()=>exportIdo('xlsx'));

$('orderedIndex').onclick=run(()=>{const scope=$('gradeScope').value;const rows=[...state.pending,...state.records].filter(r=>r.batchSource&&(scope===ALL||r.examId===scope)).sort((a,b)=>a.code.localeCompare(b.code,'es',{numeric:true}));if(!rows.length)throw Error('No hay exámenes importados sin código.');const csv='\ufeff'+[['Código','Prueba','Referencia PDF','Nº en PDF','Primera página','Última página','Nota técnica exacta','Calificación docente'],...rows.map(r=>[r.code,state.exams.find(e=>e.id===r.examId)?.title,r.batchSource.hash.slice(0,12),r.batchSource.ordinal,r.batchSource.start,r.batchSource.end,r.grade?exactLabel(r.grade):'',r.grade?officialGrade(r.grade):''])].map(row=>row.map(csvCell).join(';')).join('\r\n');download('auto-ger-indice-examenes-sin-codigo.csv',csv,'text/csv;charset=utf-8');status('Índice anónimo preparado. Usa el orden del PDF original para identificar cada examen.')});
$('allCorrected').onclick=run(async()=>{const scope=$('gradeScope').value;const records=state.records.filter(r=>(scope===ALL||r.examId===scope)&&r.photos?.length).sort((a,b)=>a.code.localeCompare(b.code,'es',{numeric:true}));if(!records.length)throw Error('No hay exámenes anotados en esta selección.');const pages=records.reduce((n,r)=>n+r.photos.length,0);if(pages>150)throw Error('Máximo 150 hojas originales por exportación conjunta. Selecciona una prueba más pequeña.');const readyRecords=[];for(const r of records)readyRecords.push(await correctionRecord(r));download('auto-ger-examenes-corregidos.pdf',collectivePDF(readyRecords),'application/pdf');status('PDF conjunto preparado. Incluye '+records.length+' exámenes con páginas conservadas.')});

$('printHeader').oninput=()=>{draft.printHeader=$('printHeader').value.trim();invalidateCreator()};

$('deleteClasses').onclick=run(async()=>{if(!confirm('¿Eliminar todos los nombres y clases de este dispositivo? Las correcciones conservan sus códigos, pero perderán la vinculación a iDoceo.'))return;const next=structuredClone(state);next.classes=[];for(const e of next.exams)delete e.classId;await commit(next);if(draft)delete draft.classId;renderClassPicker();rosterRows=[];$('rosterNames').value='';$('rosterPreview').textContent='';status('Clases eliminadas.')});

$('classesBackup').onclick=run(async()=>{const encrypted=await encryptBackup({type:'auto-ger-classes-v1',classes:state.classes},$('classesPass').value);download('auto-ger-clases-cifradas.json',JSON.stringify(encrypted),'application/json');$('classesPass').value='';status('Copia cifrada de clases preparada.')});
$('classesRestore').onchange=run(async ev=>{try{if(!ev.target.files[0])return;const data=await decryptBackup(JSON.parse(await ev.target.files[0].text()),$('classesPass').value);if(data.type!=='auto-ger-classes-v1')throw Error('No es una copia de clases.');validateClasses(data.classes);if(state.exams.some(e=>e.classId&&!data.classes.some(c=>c.id===e.classId)))throw Error('Hay pruebas vinculadas a clases no presentes en la copia. Usa una copia completa o elimina antes esas vinculaciones.');for(const old of state.classes){const restored=data.classes.find(c=>c.id===old.id);if(restored&&state.exams.some(e=>e.classId===old.id)&&old.students.some(s=>!restored.students.some(x=>x.number===s.number&&x.name===s.name)))throw Error('La correspondencia de números de una clase vinculada no coincide.')}if(!confirm('¿Sustituir las clases locales por las de la copia?'))return;const next=structuredClone(state);next.classes=data.classes;await commit(next);renderClassPicker();status('Clases restauradas.')}finally{ev.target.value='';$('classesPass').value=''}});

const uploadGroups={uploadContent:'content',uploadRubric:'rubric',uploadSolution:'solution',uploadModel:'model',uploadInstructions:'instructions'};
function countUploads(){const n=Object.keys(uploadGroups).reduce((sum,id)=>sum+$(id).files.length,0);$('uploadSummary').textContent=n?`${n} archivos preparados. Pulsa Guardar materiales.`:'Sin archivos pendientes.';return n}
for(const id of Object.keys(uploadGroups))$(id).onchange=countUploads;
$('saveLibraryPack').onclick=run(async()=>{if(!countUploads())throw Error('Selecciona archivos en alguna categoría.');const id=$('libraryFolder').value,loaded=[];for(const [input,kind] of Object.entries(uploadGroups))for(const f of $(input).files){if(!f.size||f.size>100*1024*1024)throw Error('Archivo vacío o mayor de 100 MB: '+f.name);loaded.push({kind,name:f.name,data:await read(f)})}const next=structuredClone(state);next.library=addLibraryFiles(next.library,id,loaded);await commit(next);for(const input of Object.keys(uploadGroups))$(input).value='';countUploads();renderReuse();status('Todos los materiales guardados en la carpeta seleccionada.');});
function startFromRepository(mode,folder=null,file=null){if(countUploads()&&!confirm('Hay archivos seleccionados en el repositorio sin guardar. ¿Continuar sin vincularlos?'))return false;if((draft.title||draft.materials.content.length||draft.materials.model.length||draft.materials.rubric.length)&&!confirm('¿Preparar una nueva prueba? Guarda primero los cambios pendientes.'))return false;workflowMode=mode;heldPdf=file;draft=fresh();draft.workflowMode=mode;draft.title=folder?state.library.find(f=>f.id===folder)?.title||'':'';figures=Object.create(null);creatorDraftId=null;editorDirty=false;checkedCreation=null;renderDraft();if(folder)$('reuseFolder').value=folder;$('reusePAU').checked=false;renderReuse();$('reusePanel').open=true;$('creatorPanel').open=false;$('attachedPanel').open=false;go('prepare');return true}
$('libraryCreate').onclick=run(()=>startFromRepository('create',$('libraryFolder').value));$('libraryCorrect').onclick=run(()=>startFromRepository('correct',$('libraryFolder').value));$('newScanExam').onclick=run(()=>startFromRepository('correct'));
async function activateScan(id){if((photos.length||batch)&&scanExam!==id){if(!confirm('¿Cerrar el escaneo anterior y descartar páginas sin guardar?'))return;clearPhotos();closeBatch()}$('active').value=id;scanExam=id;renderAssignedCode();go('scan');if(heldPdf){const file=heldPdf;if(await openBatchFile(file)){heldPdf=null;renderLinked();}}}
$('resumeScan').onclick=run(async()=>{if(!draft.plan)throw Error('Valida la guía primero.');await activateScan(draft.id)});
function downloadPack(exam,prompt,base,pending=null,includeMaterials=true){download(safeFileName(base)+'.zip',zipStore(packEntries(exam,prompt,pending,includeMaterials)),'application/zip');status('Paquete local descargado. Descomprime y adjunta los archivos seleccionados a ChatGPT; no adjuntes el ZIP como sustituto de los documentos.');}
$('creatorPack').onclick=run(async()=>{creatorReady();await saveDraft(false);downloadPack(draft,creatorPrompt(draft,$('creatorInstructions').value,$('creatorFormat').value),'material-creacion')});
$('guidePack').onclick=run(async()=>{ensureMaterials();await saveDraft();downloadPack(draft,planPrompt(draft),'material-guia')});

$('libraryFiles').onchange=run(async ev=>{const sel=ev.target.closest('[data-reclass]');if(!sel)return;const next=structuredClone(state),folder=next.library.find(f=>f.id===$('libraryFolder').value);const file=folder?.files[+sel.dataset.reclass];if(!file||!Object.hasOwn(materialLabels,sel.value))throw Error('Archivo o tipo inválido.');const changed={...file,kind:sel.value};folder.files.splice(+sel.dataset.reclass,1);next.library=addLibraryFiles(next.library,folder.id,[changed]);await commit(next);renderReuse();status('Tipo de material actualizado. Las pruebas validadas no se modifican.');});

$('cancelHeld').onclick=run(()=>{heldPdf=null;renderLinked();status('PDF pendiente retirado. No se ha eliminado el archivo original.');});
